// vite.config.js
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import path from 'path';

export default defineConfig({
  plugins: [react()],

  // 路径别名
  resolve: {
    alias: {
      '@': path.resolve(__dirname, 'src')
    }
  },

  // 开发服务器配置
  server: {
    port: 3000,
    proxy: {
      '/api': {
        target: 'http://localhost:8080',
        changeOrigin: true
      }
    }
  },

  // 依赖预构建配置
  optimizeDeps: {
    include: ['lodash-es', 'axios'], // 强制预构建
    exclude: ['my-local-linked-pkg'] // 排除本地链接包
  },

  // 生产构建
  build: {
    // 手动 chunk 拆分
    rollupOptions: {
      output: {
        manualChunks: {
          vendor: ['react', 'react-dom'],
          utils: ['lodash-es']
        }
      }
    },
    chunkSizeWarningLimit: 1000
  }
});

// ---- 自定义 Vite 插件示例：版本注入 ----
export function versionPlugin() {
  return {
    name: 'version-plugin',
    // 钩子：在 HTML 被处理时注入 meta 标签
    transformIndexHtml(html) {
      return html.replace(
        '</head>',
        `<meta name="version" content="${process.env.npm_package_version}" /></head>`
      );
    }
  };
}

// ---- HMR API 使用 ----
if (import.meta.hot) {
  // 接受自身模块的热更新
  import.meta.hot.accept((newModule) => {
    // newModule 是更新后的模块
  });

  // 监听事件（不触发更新，只观察）
  import.meta.hot.on('my-custom-event', (data) => {
    console.log('custom event:', data);
  });
}

// ---- 环境变量 ----
// .env                所有环境加载
// .env.development    仅开发环境
// .env.production     仅生产环境
// 只有 VITE_ 前缀的变量会暴露给客户端代码
// VITE_API_URL=http://localhost:8080
console.log(import.meta.env.VITE_API_URL);
